"use client"
import * as React from "react"
import { AnimatePresence, motion, useMotionTemplate, useMotionValue, useMotionValueEvent, useReducedMotion, useSpring, useTransform } from "framer-motion"
import { Bell, Check, Lock, Mail, MessageSquare, Moon, Sun } from "lucide-react"
import { cn } from "@/lib/utils"

export interface Channel { id: string; label: string }
export interface Topic {
  id: string
  label: string
  description: string
  /** Channels that cannot be switched off, with the reason shown to the user. */
  locked?: Record<string, string>
}
export type Digest = "instant" | "daily" | "weekly"
export interface NotificationSettings {
  matrix: Record<string, Record<string, boolean>>
  quiet: { enabled: boolean; /** minutes from midnight */ start: number; end: number }
  digest: Digest
}
export interface NotificationMatrixProps {
  channels?: Channel[]
  topics: Topic[]
  value?: NotificationSettings
  defaultValue?: NotificationSettings
  /** Time a digest arrives, shown in the summary. Default "08:00". */
  digestTime?: string
  onChange?: (s: NotificationSettings) => void
  onSave?: (s: NotificationSettings) => Promise<void>
  title?: string
  className?: string
}

const ICONS: Record<string, React.ComponentType<{ className?: string }>> = { email: Mail, push: Bell, sms: MessageSquare }
const DEFAULT_CHANNELS: Channel[] = [{ id: "email", label: "Email" }, { id: "push", label: "Push" }, { id: "sms", label: "SMS" }]
const ACCENT_TEXT = "text-primary dark:text-[color-mix(in_oklab,var(--primary),white_45%)]"
const GRADIENT = "linear-gradient(120deg,#5a49f0,#7c5cff 55%,#ff6b6b)"
const DAYNIGHT = "linear-gradient(90deg,#2d2585 0%,#5b4ff0 17%,#ff7a6b 27%,#ffd9a0 36%,#7dd3fc 50%,#ffd9a0 64%,#ff7a6b 73%,#5b4ff0 83%,#2d2585 100%)"
const hhmm = (m: number) => `${String(Math.floor((((m % 1440) + 1440) % 1440) / 60)).padStart(2, "0")}:${String(Math.round(m) % 60).padStart(2, "0")}`
const spring = { type: "spring" as const, stiffness: 520, damping: 34 }

function Switch({ on, onChange, label, disabled, locked }: { on: boolean; onChange: (v: boolean) => void; label: string; disabled?: boolean; locked?: boolean }) {
  const reduce = useReducedMotion()
  return (
    <button type="button" role="switch" aria-checked={on} aria-label={label} aria-disabled={disabled || undefined} onClick={() => !disabled && onChange(!on)}
      className={cn("group grid size-11 place-items-center rounded-xl outline-none focus-visible:outline-2 focus-visible:outline-offset-0 focus-visible:outline-ring", disabled && "cursor-not-allowed")}>
      <motion.span className={cn("relative flex h-6 w-10 items-center rounded-full px-0.5", !on && "bg-border", disabled && "opacity-80")}
        style={on ? { background: GRADIENT } : undefined}
        animate={{ boxShadow: on && !reduce ? "0 0 16px -2px rgba(124,92,255,0.85)" : "0 0 0 rgba(0,0,0,0)" }} transition={{ duration: 0.3 }}
        whileTap={reduce ? undefined : { scale: 0.92 }}>
        <motion.span layout={!reduce} transition={reduce ? { duration: 0 } : { type: "spring", stiffness: 600, damping: 22 }} whileTap={reduce ? undefined : { width: 26 }}
          className={cn("grid h-5 w-5 place-items-center rounded-full bg-white shadow-md", on && "ml-auto")}>
          {locked && <Lock className="size-2.5 text-[#5a49f0]" aria-hidden />}
        </motion.span>
      </motion.span>
    </button>
  )
}

/** 24 h two-handle slider. The handles chase the pointer on springs (inertia) and the range may wrap past midnight. */
function Quiet({ start, end, enabled, onStart, onEnd }: { start: number; end: number; enabled: boolean; onStart: (m: number) => void; onEnd: (m: number) => void }) {
  const reduce = useReducedMotion()
  const cfg = reduce ? { duration: 0 } : { stiffness: 170, damping: 15, mass: 0.9 }
  const sS = useSpring(start, cfg as never), sE = useSpring(end, cfg as never)
  const [s, setS] = React.useState(start), [e, setE] = React.useState(end)
  useMotionValueEvent(sS, "change", setS); useMotionValueEvent(sE, "change", setE)
  const prev = React.useRef({ start, end })
  React.useEffect(() => {
    // crossing midnight must not sweep across the whole track
    if (Math.abs(start - prev.current.start) > 720) sS.jump(start); else sS.set(start)
    if (Math.abs(end - prev.current.end) > 720) sE.jump(end); else sE.set(end)
    prev.current = { start, end }
  }, [start, end, sS, sE])
  const track = React.useRef<HTMLDivElement>(null)
  const [drag, setDrag] = React.useState<"start" | "end" | null>(null)
  const [focus, setFocus] = React.useState<"start" | "end" | null>(null)
  const fromX = (x: number) => { const b = track.current!.getBoundingClientRect(); return (Math.round(((Math.min(Math.max(x, b.left), b.right) - b.left) / b.width) * 96) * 15) % 1440 }
  const dist = (a: number, b: number) => Math.min(Math.abs(a - b), 1440 - Math.abs(a - b))
  const down = (ev: React.PointerEvent) => {
    if (!enabled) return
    const m = fromX(ev.clientX)
    const which = dist(m, start) <= dist(m, end) ? "start" : "end"
    setDrag(which); ev.currentTarget.setPointerCapture(ev.pointerId); (which === "start" ? onStart : onEnd)(m)
  }
  const move = (ev: React.PointerEvent) => { if (drag) (drag === "start" ? onStart : onEnd)(fromX(ev.clientX)) }
  const wrapped = ((s % 1440) + 1440) % 1440 >= ((e % 1440) + 1440) % 1440
  const ss = ((s % 1440) + 1440) % 1440, ee = ((e % 1440) + 1440) % 1440
  const dim: [number, number][] = wrapped ? [[ee, ss]] : [[0, ss], [ee, 1440]]
  const quiet: [number, number][] = wrapped ? [[ss, 1440], [0, ee]] : [[ss, ee]]
  const key = (which: "start" | "end") => (ev: React.KeyboardEvent) => {
    const m = which === "start" ? start : end, step = ev.shiftKey ? 60 : 15
    const t: Record<string, number> = { ArrowRight: m + step, ArrowUp: m + step, ArrowLeft: m - step, ArrowDown: m - step, Home: 0, End: 1425, PageUp: m + 120, PageDown: m - 120 }
    if (!(ev.key in t)) return
    ev.preventDefault(); (which === "start" ? onStart : onEnd)(((t[ev.key] % 1440) + 1440) % 1440)
  }
  const thumb = (which: "start" | "end", v: number) => {
    const m = ((v % 1440) + 1440) % 1440, night = m < 360 || m >= 1200, show = drag === which || focus === which
    return (
      <div key={which} role="slider" tabIndex={0} aria-label={`Quiet hours ${which}`} aria-valuemin={0} aria-valuemax={1439} aria-valuenow={which === "start" ? start : end} aria-valuetext={hhmm(which === "start" ? start : end)}
        data-thumb onKeyDown={key(which)} onFocus={() => setFocus(which)} onBlur={() => setFocus(null)}
        className="group absolute top-1/2 z-10 grid size-11 -translate-x-1/2 -translate-y-1/2 cursor-grab touch-none place-items-center outline-none active:cursor-grabbing" style={{ left: `${(m / 1440) * 100}%` }}>
        <motion.span animate={{ scale: drag === which && !reduce ? 1.35 : 1 }} transition={{ type: "spring", stiffness: 500, damping: 18 }}
          className="grid size-6 place-items-center rounded-full border-2 border-white bg-[#5a49f0] text-white shadow-[0_4px_14px_rgba(90,73,240,0.7)] group-focus-visible:outline-2 group-focus-visible:outline-offset-2 group-focus-visible:outline-ring">
          {night ? <Moon className="size-3" aria-hidden /> : <Sun className="size-3" aria-hidden />}
        </motion.span>
        <AnimatePresence>
          {show && <motion.span initial={{ opacity: 0, y: reduce ? 0 : 8, scale: 0.8 }} animate={{ opacity: 1, y: 0, scale: 1 }} exit={{ opacity: 0 }} className="pointer-events-none absolute -top-7 rounded-md bg-foreground px-1.5 py-0.5 text-[11px] font-medium tabular-nums text-background">{hhmm(v)}</motion.span>}
        </AnimatePresence>
      </div>
    )
  }
  return (
    <div className={cn("select-none px-3 transition-opacity", !enabled && "pointer-events-none opacity-45")} aria-disabled={!enabled}>
      <div className="relative h-11" onPointerDown={down} onPointerMove={move} onPointerUp={() => setDrag(null)} onPointerCancel={() => setDrag(null)}>
        <div ref={track} className="absolute inset-x-0 top-1/2 h-3.5 -translate-y-1/2 rounded-full shadow-[inset_0_0_0_1px_rgba(255,255,255,0.15)]" style={{ background: DAYNIGHT }}>
          {dim.map(([a, b], i) => <span key={i} className="absolute inset-y-0 bg-card/80" style={{ left: `${(a / 1440) * 100}%`, width: `${((b - a) / 1440) * 100}%`, borderRadius: 999 }} />)}
          {quiet.map(([a, b], i) => <span key={`q${i}`} aria-hidden className="absolute -inset-y-1 rounded-full ring-2 ring-white/70 shadow-[0_0_18px_rgba(124,92,255,0.8)]" style={{ left: `${(a / 1440) * 100}%`, width: `${((b - a) / 1440) * 100}%` }} />)}
          {[0, 6, 12, 18, 24].map((h) => <span key={h} aria-hidden className="absolute top-full mt-2 -translate-x-1/2 text-[10px] tabular-nums text-muted-foreground" style={{ left: `${(h / 24) * 100}%` }}>{String(h % 24).padStart(2, "0")}</span>)}
        </div>
        {thumb("start", s)}{thumb("end", e)}
      </div>
      <div className="h-4" />
    </div>
  )
}

export function NotificationMatrix({
  channels = DEFAULT_CHANNELS, topics, value, defaultValue, digestTime = "08:00", onChange, onSave, title = "Notifications", className,
}: NotificationMatrixProps) {
  const reduce = useReducedMotion()
  const uid = React.useId()
  const init = React.useRef<NotificationSettings>(value ?? defaultValue ?? { matrix: {}, quiet: { enabled: false, start: 1320, end: 420 }, digest: "instant" })
  const [inner, setInner] = React.useState<NotificationSettings>(init.current)
  const [saved, setSaved] = React.useState<NotificationSettings>(init.current)
  const [status, setStatus] = React.useState<"idle" | "saving" | "done">("idle")
  const s = value ?? inner
  const [hot, setHot] = React.useState<{ r: number; c: number } | null>(null)
  const [pulse, setPulse] = React.useState<{ r: number; c: number; n: number } | null>(null)
  const [lockNote, setLockNote] = React.useState("")

  const mx = useMotionValue(0.5), my = useMotionValue(0.5)
  const rx = useSpring(useTransform(my, [0, 1], [2.5, -2.5]), { stiffness: 120, damping: 18 }), ry = useSpring(useTransform(mx, [0, 1], [-3.5, 3.5]), { stiffness: 120, damping: 18 })
  const px = useMotionValue(-300), py = useMotionValue(-300)
  const glow = useMotionTemplate`radial-gradient(280px circle at ${px}px ${py}px, color-mix(in oklab, var(--primary) 14%, transparent), transparent 70%)`

  const update = (n: NotificationSettings) => { setInner(n); setStatus("idle"); onChange?.(n) }
  const dirty = JSON.stringify(s) !== JSON.stringify(saved)
  const cell = (t: Topic, c: Channel) => (t.locked?.[c.id] ? true : !!s.matrix[t.id]?.[c.id])
  const toggle = (t: Topic, c: Channel, v: boolean, r: number, ci: number) => {
    update({ ...s, matrix: { ...s.matrix, [t.id]: { ...s.matrix[t.id], [c.id]: v } } })
    setPulse((p) => ({ r, c: ci, n: (p?.n ?? 0) + 1 }))
  }
  const total = topics.length * channels.length
  const onCount = topics.reduce((n, t) => n + channels.filter((c) => cell(t, c)).length, 0)
  const setQuiet = (p: Partial<NotificationSettings["quiet"]>) => update({ ...s, quiet: { ...s.quiet, ...p } })
  const { start, end } = s.quiet
  const hours = (((end - start) % 1440) + 1440) % 1440 / 60

  const digestOptions: { id: Digest; label: string; text: string }[] = [
    { id: "instant", label: "Right away", text: "Each notification arrives the moment it happens." },
    { id: "daily", label: "Daily", text: `One summary a day at ${digestTime}. Security alerts still arrive right away.` },
    { id: "weekly", label: "Weekly", text: `One summary every Monday at ${digestTime}. Security alerts still arrive right away.` },
  ]
  const digestKey = (e: React.KeyboardEvent, i: number) => {
    const d = e.key === "ArrowRight" || e.key === "ArrowDown" ? 1 : e.key === "ArrowLeft" || e.key === "ArrowUp" ? -1 : 0
    if (!d) return
    e.preventDefault()
    update({ ...s, digest: digestOptions[(i + d + 3) % 3].id })
    ;(e.currentTarget.parentElement?.children[(i + d + 3) % 3] as HTMLElement | undefined)?.focus()
  }
  const save = async () => { setStatus("saving"); try { await onSave?.(s); setSaved(s); setStatus("done") } catch { setStatus("idle") } }
  const cols = { gridTemplateColumns: `minmax(0,1fr) repeat(${channels.length}, 3rem)` }
  const dist = (r: number, c: number) => (hot ? (r === hot.r ? Math.abs(c - hot.c) : c === hot.c ? Math.abs(r - hot.r) : -1) : -1)

  return (
    <div className={cn("relative w-full max-w-xl", className)} style={{ perspective: 1200 }}>
      <motion.div aria-hidden className="pointer-events-none absolute -inset-3 rounded-[2rem] bg-[conic-gradient(from_300deg,#6c5cff,#22d3ee,#ff6b6b,#6c5cff)] blur-2xl"
        animate={reduce ? { opacity: 0.25 } : { opacity: [0.2, 0.42, 0.2], rotate: [0, -5, 0] }} transition={{ duration: 6, repeat: Infinity, ease: "easeInOut" }} />
      <motion.section aria-label={title}
        onPointerMove={(e) => { const b = e.currentTarget.getBoundingClientRect(); mx.set((e.clientX - b.left) / b.width); my.set((e.clientY - b.top) / b.height); px.set(e.clientX - b.left); py.set(e.clientY - b.top) }}
        onPointerLeave={() => { mx.set(0.5); my.set(0.5) }}
        style={{ rotateX: reduce ? 0 : rx, rotateY: reduce ? 0 : ry, transformStyle: "preserve-3d" }}
        initial={{ opacity: 0, y: reduce ? 0 : 24 }} animate={{ opacity: 1, y: 0 }} transition={{ type: "spring", stiffness: 140, damping: 18 }}
        className="relative rounded-2xl border border-border bg-card p-5 text-foreground shadow-[0_40px_70px_-35px_rgba(50,35,150,0.5)] sm:p-6">
        {!reduce && <motion.div aria-hidden className="pointer-events-none absolute inset-0 rounded-2xl" style={{ background: glow }} />}
        <header className="relative flex items-baseline justify-between gap-3" style={{ transform: "translateZ(20px)" }}>
          <h2 className="text-lg font-semibold leading-tight">{title}</h2>
          <p className="text-xs tabular-nums text-muted-foreground" aria-live="polite">{onCount} of {total} on</p>
        </header>

        <div className="relative mt-4" style={{ transform: "translateZ(14px)" }} onMouseLeave={() => { setHot(null); setLockNote("") }}>
          <div className="grid items-end pb-1 text-xs" style={cols} aria-hidden>
            <span />
            {channels.map((c, ci) => { const I = ICONS[c.id]; return <span key={c.id} className={cn("flex flex-col items-center gap-0.5 transition-colors", hot?.c === ci ? "font-semibold text-foreground" : "text-muted-foreground")}>{I && <I className="size-3.5" />}{c.label}</span> })}
          </div>
          <div role="group" aria-label="Where to notify you, by topic">
            {topics.map((t, ri) => (
              <div key={t.id} className="grid items-center border-t border-border/70" style={cols}>
                <div className="py-2 pr-2">
                  <p className={cn("text-sm font-medium transition-colors", hot?.r === ri && ACCENT_TEXT)}>{t.label}</p>
                  <p className="text-xs text-muted-foreground">{t.description}</p>
                </div>
                {channels.map((c, ci) => {
                  const reason = t.locked?.[c.id], d = dist(ri, ci)
                  const pd = pulse && pulse.r === ri ? Math.abs(ci - pulse.c) : -1
                  const note = reason ? `${t.label} by ${c.label.toLowerCase()} stays on: ${reason}` : ""
                  return (
                    <div key={c.id} className="relative grid place-items-center" onMouseEnter={() => { setHot({ r: ri, c: ci }); setLockNote(note) }} onFocus={() => { setHot({ r: ri, c: ci }); setLockNote(note) }}>
                      <motion.span aria-hidden className="pointer-events-none absolute inset-0.5 rounded-xl" style={{ background: GRADIENT }} initial={false}
                        animate={{ opacity: d < 0 ? 0 : Math.max(0, 0.22 - d * 0.07) }} transition={{ type: "spring", stiffness: 300, damping: 24, delay: reduce || d < 0 ? 0 : d * 0.04 }} />
                      <motion.div key={pulse ? `${pulse.n}-${pd}` : "x"} animate={!reduce && pd >= 0 ? { scale: [1, 1.28, 1], y: [0, -4, 0] } : { scale: 1 }} transition={{ duration: 0.45, delay: pd * 0.07 }}>
                        <Switch on={cell(t, c)} locked={!!reason} disabled={!!reason} label={`${t.label} by ${c.label}${reason ? ", always on" : ""}`} onChange={(v) => toggle(t, c, v, ri, ci)} />
                      </motion.div>
                    </div>
                  )
                })}
              </div>
            ))}
          </div>
          <p aria-live="polite" className="mt-1 h-4 text-xs text-muted-foreground">{lockNote}</p>
        </div>

        <div className="relative mt-4 rounded-xl border border-border bg-background p-4" style={{ transform: "translateZ(10px)" }}>
          <div className="flex items-center justify-between gap-3">
            <div>
              <p className="flex items-center gap-1.5 text-sm font-medium"><Moon className="size-4" aria-hidden /> Quiet hours</p>
              <p className="mt-0.5 text-xs text-muted-foreground" aria-live="polite">
                {s.quiet.enabled ? <>Silent from <span className="font-medium tabular-nums text-foreground">{hhmm(start)}</span> to <span className="font-medium tabular-nums text-foreground">{hhmm(end)}</span>, {Number.isInteger(hours) ? hours : hours.toFixed(1)} h a day.</> : "Off. Everything arrives whenever it happens."}
              </p>
            </div>
            <Switch on={s.quiet.enabled} onChange={(v) => setQuiet({ enabled: v })} label="Quiet hours" />
          </div>
          <div className="mt-5"><Quiet start={start} end={end} enabled={s.quiet.enabled} onStart={(m) => setQuiet({ start: m })} onEnd={(m) => setQuiet({ end: m })} /></div>
        </div>

        <div className="relative mt-4" style={{ transform: "translateZ(8px)" }}>
          <p id={`${uid}-d`} className="mb-2 text-sm font-medium">How often should we bundle them?</p>
          <div role="radiogroup" aria-labelledby={`${uid}-d`} className="grid grid-cols-3 gap-1 rounded-xl bg-muted p-1">
            {digestOptions.map((o, i) => {
              const on = s.digest === o.id
              return (
                <button key={o.id} type="button" role="radio" aria-checked={on} tabIndex={on ? 0 : -1} onClick={() => update({ ...s, digest: o.id })} onKeyDown={(e) => digestKey(e, i)}
                  className={cn("relative min-h-11 rounded-lg text-sm font-medium outline-none transition-colors focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring", on ? "text-white" : "text-muted-foreground hover:text-foreground")}>
                  {on && <motion.span layoutId="digest-pill" transition={reduce ? { duration: 0 } : { type: "spring", stiffness: 380, damping: 20 }} className="absolute inset-0 rounded-lg shadow-[0_6px_18px_-6px_rgba(108,92,255,0.9)]" style={{ background: GRADIENT }} />}
                  <span className="relative">{o.label}</span>
                </button>
              )
            })}
          </div>
          <div className="mt-2 min-h-10 text-sm text-muted-foreground" aria-live="polite">
            <AnimatePresence mode="wait" initial={false}>
              <motion.p key={s.digest} initial={{ opacity: 0, y: reduce ? 0 : 8 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }} transition={{ duration: 0.15 }}>{digestOptions.find((o) => o.id === s.digest)!.text}</motion.p>
            </AnimatePresence>
          </div>
        </div>

        <AnimatePresence initial={false}>
          {(dirty || status === "done") && (
            <motion.div key="bar" initial={{ height: 0, opacity: 0 }} animate={{ height: "auto", opacity: 1 }} exit={{ height: 0, opacity: 0 }} transition={reduce ? { duration: 0.01 } : spring} className="relative overflow-hidden">
              <div className="mt-3 flex items-center justify-end gap-2 border-t border-border pt-3">
                {status === "done" && !dirty ? (
                  <p role="status" className={cn("flex min-h-11 items-center gap-1.5 text-sm font-medium", ACCENT_TEXT)}><Check className="size-4" aria-hidden /> Saved</p>
                ) : (
                  <>
                    <button type="button" onClick={() => update(saved)} className="min-h-11 rounded-xl px-4 text-sm text-muted-foreground outline-none hover:text-foreground focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring">Undo</button>
                    <motion.button type="button" onClick={save} disabled={status === "saving"} whileTap={reduce ? undefined : { scale: 0.95 }} style={{ background: GRADIENT }}
                      className="min-h-11 rounded-xl px-5 text-sm font-semibold text-white shadow-[0_10px_24px_-8px_rgba(108,92,255,0.8)] outline-none focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring disabled:opacity-60">
                      {status === "saving" ? "Saving" : "Save changes"}
                    </motion.button>
                  </>
                )}
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </motion.section>
    </div>
  )
}

export default function Demo() {
  const topics: Topic[] = [
    { id: "replies", label: "Replies", description: "Someone answers your comment" },
    { id: "mentions", label: "Mentions", description: "Someone tags you by name" },
    { id: "news", label: "Product news", description: "New features, once in a while" },
    { id: "security", label: "Security alerts", description: "Sign-ins from new devices", locked: { email: "it protects your account." } },
  ]
  return (
    <NotificationMatrix
      topics={topics}
      defaultValue={{
        matrix: { replies: { email: true, push: true }, mentions: { push: true, sms: false }, news: { email: false }, security: { push: true, sms: true } },
        quiet: { enabled: true, start: 22 * 60, end: 7 * 60 }, digest: "daily",
      }}
      onSave={() => new Promise((r) => setTimeout(r, 800))}
    />
  )
}

